    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "batch-a@invite-bulk-quota.test", role: "member" },
          { email: "batch-b@invite-bulk-quota.test", role: "member" },
